#include <iostream>
#include <vector>
#include <algorithm>
using namespace std;

int main() {
    vector<int> v;
    v.push_back(3);
    v.push_back(8);
    v.push_back(1);
    sort(v.begin(), v.end(), [](int a, int b) {
        return a > b;
    });
    cout << v[0] << endl;
    cout << v[2] << endl;
    return 0;
}

#include <iostream>
#include <vector>
#include <algorithm>
using namespace std;

int main() {
    vector<int> v;
    v.push_back(1);
    v.push_back(2);
    v.push_back(3);
    transform(v.begin(), v.end(), v.begin(), [](int x) {
        return x + 10;
    });
    cout << count(v.begin(), v.end(), 12) << endl;
    cout << v[1] << endl;
    return 0;
}
